#!/usr/bin/env python3
"""Redo, with the primary image model, the images that were generated by the Gemini fallback.
usage: godot-kit regen-images [--game <game_id>] [--dry-run]
Rows that succeed are removed from fallback_log.tsv. If OpenAI still has no credit, nothing changes."""
import json, pathlib, subprocess, sys
HERE = pathlib.Path(__file__).resolve().parent
sys.path.insert(0, str(HERE.parent / "lib"))
import kitconf
LOG = kitconf.LOGS / "fallback_log.tsv"
lines = [l for l in LOG.read_text().splitlines() if l.strip()] if LOG.exists() else []
game = sys.argv[sys.argv.index("--game") + 1] if "--game" in sys.argv else None
keep = []
for idx, l in enumerate(lines):
    ts, out, args = l.split("\t", 2)
    if game and f"/{game}/" not in out:
        keep.append(l); continue
    args = json.loads(args)
    import datetime, os
    try:  # do not overwrite a file that someone remade after the fallback was recorded
        if os.path.getmtime(out) > datetime.datetime.fromisoformat(ts).timestamp() + 120:
            print("skip (updated after fallback)", out); continue
    except FileNotFoundError:
        print("skip (missing)", out); continue
    if "--dry-run" in sys.argv:
        print(out); keep.append(l); continue
    tmp = out + ".regen.png"
    r = subprocess.run([sys.executable, str(HERE / "gen_image.py"), tmp] + args, capture_output=True, text=True)
    if "Gemini" in r.stderr:
        print("OpenAI is still unavailable. Stopping."); keep += lines[idx:]; pathlib.Path(tmp).unlink(missing_ok=True); break
    if r.returncode != 0:
        print("failed (skip):", out, (r.stdout + r.stderr).strip()[-300:]); keep.append(l); pathlib.Path(tmp).unlink(missing_ok=True); continue
    pathlib.Path(tmp).replace(out); print("regenerated", out)
if LOG.exists():
    LOG.write_text("\n".join(keep) + ("\n" if keep else ""))
